<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">WRITER ADMINISTRATION</span><h2><?=e($writer['display_name']?:$writer['name'])?></h2><p>@<?=e($writer['username'])?> · <?=e($writer['email'])?> · إدارة الملف العام، المحتوى والتكريمات دون كشف حقول خاصة للزوار.</p></div><a class="admin-v2-button ghost" href="/admin-v2/writers">عودة إلى الكتّاب</a></section>
<section class="admin-v2-grid-2"><div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>الملف العام</h3><span><?=!empty($writer['is_public'])?'ظاهر':'مخفي'?></span></div><dl class="admin-v2-detail-list"><div><dt>الاسم المهني</dt><dd><?=e($writer['display_name']?:$writer['name'])?></dd></div><div><dt>المسمى</dt><dd><?=e($writer['professional_title']??'—')?></dd></div><div><dt>النبذة</dt><dd><?=nl2br(e($writer['bio']?:$writer['cv_summary']??'—'))?></dd></div><div><dt>الحالة</dt><dd><?=e($writer['status'])?> · <?=e($writer['role'])?></dd></div></dl><form method="post" action="/admin-v2/writers/action" class="admin-v2-inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($writer['id'])?>"><input type="hidden" name="action" value="<?=!empty($writer['writer_directory_hidden'])?'restore_profile':'hide'?>"><button class="admin-v2-button <?=!empty($writer['writer_directory_hidden'])?'primary':'ghost'?>"><?=!empty($writer['writer_directory_hidden'])?'إظهار الملف':'إخفاء الملف'?></button></form></div><div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>مراسلة الكاتب</h3><span>مسار الرسائل التحريرية</span></div><form method="post" action="/admin/editorial-messages/create" class="admin-v2-actions"><?=csrf_field()?><input type="hidden" name="writer_id" value="<?=e($writer['id'])?>"><label>الموضوع<input name="subject" maxlength="190" required></label><button class="admin-v2-button primary">بدء محادثة</button></form><p class="admin-v2-muted">تُحفظ الرسالة في نظام المراسلات الحالي وتظهر للكاتب داخل حسابه.</p></div></section>
<section class="admin-v2-grid-2"><div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>التكريمات والجوائز</h3><span><?=count($awards)?></span></div><form method="post" action="/admin-v2/writers/award/save" class="admin-v2-actions"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=e($writer['id'])?>"><label>عنوان التكريم<input name="title" maxlength="190" required></label><label>الرسالة<textarea name="message" rows="3"></textarea></label><label>النوع<select name="award_type"><option value="featured">مميز</option><option value="editorial">تحرير</option><option value="community">منتدى</option></select></label><button class="admin-v2-button primary">إضافة تكريم</button></form><div class="admin-v2-shortcuts"><?php foreach($awards as $award):?><div><strong><?=e($award['title'])?></strong><small><?=e($award['message']??'')?> · <?=!empty($award['active'])?'فعال':'مخفي'?></small><?php if(!empty($award['active'])):?><form method="post" action="/admin-v2/writers/award/delete"><?=csrf_field()?><input type="hidden" name="award_id" value="<?=e($award['id'])?>"><button class="admin-v2-small-button danger">إخفاء</button></form><?php endif;?></div><?php endforeach;?></div></div><div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>المحتوى</h3><span><?=count($articles)?> مقال · <?=count($thoughts)?> خاطرة</span></div><div class="admin-v2-shortcuts"><?php foreach($articles as $article):?><a href="/writer/articles/<?=e($article['id'])?>">مقال: <?=e($article['title']?:'بدون عنوان')?> <small><?=e($article['status'])?></small></a><?php endforeach; foreach($thoughts as $thought):?><a href="/admin/khawatir/<?=e($thought['id'])?>">خاطرة: <?=e($thought['title']?:mb_substr((string)($thought['body']??''),0,80))?> <small><?=e($thought['status'])?></small></a><?php endforeach; if(!$articles&&!$thoughts):?><div class="admin-v2-empty small">لا يوجد محتوى مرتبط.</div><?php endif;?></div></div></section>
<section class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>سجل الكاتب</h3><span><?=count($history)?></span></div><div class="admin-v2-result-list"><?php foreach($history as $entry):?><div><span><?=e($entry['action'])?></span><small><?=e($entry['created_at'])?></small></div><?php endforeach; if(!$history):?><div class="admin-v2-empty small">لا يوجد سجل متاح.</div><?php endif;?></div></section>
